"""Render native HTML/CSS motion-design plates using the app's actual font and artwork."""
from pathlib import Path
import base64
ROOT=Path(__file__).resolve().parent; W=ROOT/'work'; G=W/'game'; OUT=W/'render'; OUT.mkdir(exist_ok=True)
font=(G/'node_modules/@fontsource-variable/nunito/files/nunito-latin-wght-normal.woff2').read_bytes()
def data(p):
 p=Path(p); mime='image/webp' if p.suffix=='.webp' else 'image/png'
 return f'data:{mime};base64,'+base64.b64encode(p.read_bytes()).decode()
def art(name):return data(G/'public/art'/f'{name}-256.webp')
def image(name,cls='',style=''):return f'<img class="{cls}" style="{style}" src="{art(name)}">'
fontdata=base64.b64encode(font).decode()
css=f'''@font-face{{font-family:Nunito;src:url(data:font/woff2;base64,{fontdata});font-weight:200 1000;font-display:block}}'''+'''
*{box-sizing:border-box}html,body{margin:0;background:transparent;font-family:Nunito,sans-serif;color:#7a3b0c} .plate{position:relative;width:1920px;height:1080px;overflow:hidden;display:none}.bg{background:radial-gradient(ellipse at 78% 28%,#ffedba 0,transparent 55%),linear-gradient(130deg,#fffdf5,#fff3db)}.bg.blue{background:radial-gradient(ellipse at 55% 40%,#fffaf0,transparent 65%),linear-gradient(125deg,#e6edff,#f5f7ff)}.bg.green{background:radial-gradient(ellipse at 65% 30%,#fcf5d5,transparent 58%),linear-gradient(125deg,#edf8e7,#fffbef)}.bg:after{content:'';position:absolute;inset:0;background-image:radial-gradient(#a9773e30 .8px,transparent .9px);background-size:24px 24px;opacity:.3}.halo{position:absolute;width:920px;height:920px;border:2px solid #d9b26335;border-radius:50%;right:-90px;top:80px}.halo:before{content:'';position:absolute;inset:50px;border:2px dashed #d9b26340;border-radius:50%}.math{position:absolute;width:92px;height:92px;display:grid;place-items:center;background:#fff9ec;border:2px solid #decaa4;border-radius:23px;box-shadow:0 12px 0 #dbc49940;font-size:58px;font-weight:1000;color:#b28755;opacity:.48}.decor{position:absolute;object-fit:contain}.dot{position:absolute;width:10px;height:10px;background:#d8a944;border-radius:3px;transform:rotate(20deg);opacity:.5}.titles{background:transparent}.kicker{position:absolute;left:140px;top:126px;font-size:25px;font-weight:950;letter-spacing:5px;text-transform:uppercase;color:#a36729}.head{position:absolute;left:140px;top:208px;margin:0;width:900px;font-size:102px;line-height:1.04;letter-spacing:-3px;font-weight:1000}.head span{color:#c67717}.sub{position:absolute;left:145px;top:578px;width:845px;font-size:33px;line-height:1.4;font-weight:650;color:#916438}.pill{position:absolute;left:145px;top:780px;display:flex;gap:20px;align-items:center;padding:18px 28px;border:2px solid #b7d2ae;background:#edf7e8;border-radius:24px;font-size:29px;font-weight:850;color:#347047}.pill img{width:57px;height:57px;object-fit:contain}.right .kicker{left:875px}.right .head{left:870px;width:900px;font-size:94px}.right .sub{left:875px;width:840px}.right .pill{left:875px}.equation{position:absolute;left:140px;top:728px;display:flex;gap:16px;align-items:center}.number{width:148px;height:96px;border:3px solid #a47742;border-radius:17px;display:grid;place-items:center;font-weight:950;font-size:44px;background:#fff7e6;box-shadow:0 8px 0 #c9a66d35}.op{width:48px;text-align:center;font-weight:1000;font-size:44px}.answer{width:112px;background:#ffdb58;transform:rotate(-3deg)}.answer-chip{position:absolute;left:368px;top:728px;width:112px;height:96px;background:#cae8bf;border:3px solid #8bb77d;border-radius:17px;display:grid;place-items:center;font-size:46px;font-weight:1000;color:#316c40;transform:rotate(-3deg);box-shadow:0 8px 0 #c9a66d35}.op-row{position:absolute;left:875px;top:775px;display:flex;gap:20px}.op-tile{width:104px;height:104px;display:grid;place-items:center;border:2px solid #e2c08a;border-radius:24px;background:#fff4d7;font-weight:1000;font-size:63px;box-shadow:0 10px 0 #dec49b44}.center-kicker{position:absolute;top:45px;left:0;width:100%;text-align:center;font-size:25px;letter-spacing:5px;font-weight:950;color:#4c66ad}.center-head{position:absolute;top:95px;left:0;width:100%;text-align:center;font-size:88px;font-weight:1000;letter-spacing:-2px;color:#344d9d}.center-sub{position:absolute;top:199px;left:0;width:100%;text-align:center;font-size:30px;font-weight:650;color:#677697}.group-label{position:absolute;top:265px;width:300px;text-align:center;font-size:23px;letter-spacing:3px;font-weight:900;color:#4c66ad}.mode-row{position:absolute;left:890px;display:flex;align-items:center;gap:28px;font-size:56px;font-weight:1000}.mode-row img{width:100px;height:100px;object-fit:contain}.mode-row small{display:block;font-size:27px;font-weight:650;letter-spacing:0;color:#916438}.brand{position:absolute;left:135px;top:245px;font-size:143px;line-height:1;font-weight:1000;letter-spacing:-5px}.brand small{display:block;font-size:38px;letter-spacing:12px;padding-left:8px;margin-top:28px;color:#b36519}.cta{position:absolute;left:140px;top:655px;display:flex;align-items:center;gap:22px;padding:25px 35px;border:3px solid #e5bd68;border-radius:28px;background:#fffdf5;box-shadow:0 12px 0 #d8b37b38;font-size:32px;font-weight:900}.cta img{width:50px;height:50px}.credit{position:absolute;left:145px;top:925px;font-size:23px;line-height:1.4;font-weight:650;color:#916c47}.screen-mask{width:430px;height:900px;background:black}.screen-mask:before{content:'';position:absolute;inset:0;border-radius:29px;background:white}.device{position:absolute;left:65px;top:20px;width:470px;height:1020px;border:2px solid #b89669;border-radius:63px;background:linear-gradient(125deg,#6f553b,#1c1915 11%,#211c17 78%,#806447);box-shadow:inset 2px 1px 2px #fff5dc90,inset -2px -1px 2px #000,17px 18px 35px #7c4c252b}.device:before{content:'';position:absolute;inset:7px;border:1px solid #9e7c5250;border-radius:55px;background:linear-gradient(110deg,#35281f,#171511 30%,#211d17)}.camera{position:absolute;left:261px;top:43px;width:79px;height:12px;background:#0f0e0b;border-radius:20px;box-shadow:inset 0 1px 2px #ffffff16}.camera:after{content:'';position:absolute;right:8px;top:3px;width:6px;height:6px;border-radius:50%;background:#304147;box-shadow:inset 0 0 2px black}.home-bar{position:absolute;left:255px;top:1009px;width:90px;height:5px;border-radius:20px;background:#ad947040}.side{position:absolute;background:linear-gradient(90deg,#443522,#a7895d);border-radius:3px;left:60px;width:6px}.side.one{top:160px;height:40px}.side.two{top:220px;height:70px}.side.three{left:534px;top:220px;height:90px}
'''
def background(i,kind=''):
 right=i not in [1,3,5]
 bx='right:-65px;top:70px;width:215px;height:215px;transform:rotate(17deg)' if right else 'left:-30px;top:755px;width:190px;height:190px;transform:rotate(-14deg)'
 deco=image('star','decor',bx)
 return f'<section class="plate bg {kind}" id="bg{i}"><div class="halo" style="'+('left:-100px;right:auto' if not right else '')+'"></div>'+deco+f'<div class="math" style="left:45px;top:825px;transform:rotate(-10deg)">+</div><div class="math" style="right:45px;top:695px;transform:rotate(12deg)">×</div><i class="dot" style="left:980px;top:120px"></i><i class="dot" style="left:1035px;top:890px"></i></section>'
def title(i,body,classes=''):
 return f'<section class="plate titles {classes}" id="title{i}">{body}</section>'
def kicker(s):return f'<div class="kicker">{s}</div>'
def head(s):return f'<h1 class="head">{s}</h1>'
def sub(s,style=''):return f'<div class="sub" style="{style}">{s}</div>'
def pill(name,text):return f'<div class="pill">{image(name)}{text}</div>'
parts=[]
for i,k in enumerate(['','','green','','blue','green','']):parts.append(background(i,k))
parts.append(title(0,kicker('INTEGRID · IN ACTION')+head('Find the<br><span>missing</span><br>number.')+sub('An integer crossword adventure.<br>One satisfying answer at a time.')+'<div class="equation"><span class="number">(−12)</span><span class="op">+</span><span class="number answer">?</span><span class="op">=</span><span class="number">(−19)</span></div>'))
parts.append(title(1,kicker('RELAX MODE')+head('Learn the signs.<br><span>Solve the grid.</span>')+sub('Take your time.<br>A free clue is just a tap away.')+pill('book','A little help. A new “aha!”'),'right'))
parts.append(title(2,kicker('MAKE EVERY BOX COUNT')+head('Clear the grid.<br><span>Celebrate</span><br>the win.')+sub('Earn coins when you finish a level.<br>Keep your adventure moving.')+pill('coin','Real progress, one puzzle at a time.')))
parts.append(title(3,kicker('EXPERT MODE')+head('A bigger grid.<br><span>A new challenge.</span>')+sub('Mix your operations.<br>Test your integer skills.')+'<div class="op-row">'+''.join(f'<div class="op-tile">{s}</div>' for s in ['+','−','×','÷'])+'</div>','right'))
parts.append(title(4,'<div class="center-kicker">CLASSROOM BATTLES</div><div class="center-head">Team up. Race the grid.</div><div class="center-sub">Shared puzzles. Live progress. Friendly competition.</div><div class="group-label" style="left:485px">GROUP 1</div><div class="group-label" style="left:1120px">GROUP 2</div>'))
parts.append(title(5,kicker('PLAY YOUR WAY')+head('Choose your<br><span>adventure.</span>')+''.join(f'<div class="mode-row" style="top:{y}px;color:{color}">{image(icon)}<div>{name}<small>{desc}</small></div></div>' for y,color,icon,name,desc in [(490,'#267848','leaf','RELAX','Learn at your own pace.'),(665,'#a65016','flame','EXPERT','Take on the challenge.'),(840,'#3d57a5','sword','BATTLE','Play together. Aim higher.')]),'right'))
parts.append(title(6,kicker('YOUR INTEGER ADVENTURE')+'<div class="brand">INTEGRID<small>IN ACTION</small></div>'+sub('A Math Crossword Adventure!',style='top:495px;font-size:39px;font-weight:850')+'<div class="cta">'+image('target')+'integrid-phi.vercel.app <span style="color:#b77523">↗</span></div><div class="credit">Music by Eric Matyas<br>www.soundimage.org</div>'))
parts.append('<section class="plate titles" id="answer0"><div class="answer-chip">(−7)</div></section>')
parts.append('<section class="plate" id="phone" style="width:600px;height:1080px"><div class="device"></div><span class="side one"></span><span class="side two"></span><span class="side three"></span><div class="camera"></div><div class="home-bar"></div></section>')
parts.append('<section class="plate screen-mask" id="mask"></section>')
(OUT/'art.html').write_text('<!doctype html><html><head><meta charset="utf-8"><style>'+css+'</style></head><body>'+''.join(parts)+'</body></html>')
print('Native artwork plates prepared:',OUT/'art.html')
